def diet_plan_performance(calories, k, lower, upper):
    points = 0
    window_sum = sum(calories[:k])

    def score(total):
        if total < lower:
            return -1
        if total > upper:
            return 1
        return 0

    points += score(window_sum)
    for i in range(k, len(calories)):
        window_sum += calories[i] - calories[i - k]
        points += score(window_sum)

    return points

